"""Generate completion_phase_3a.js: resume the agents stopped by the session limit (2026-10-08 ~08:50) and add
the textbook tasks that no other agent owns.  Reuses the exact constants and task texts of phase 2b-1 / 2b-2."""
import re
import sys

REPO = "D:/Developer/github/Dirac_claude/Revision/workflows/completion/"
b1 = open(REPO + "completion_phase_2b1.js", encoding="utf-8").read()
b2 = open(REPO + "completion_phase_2b2.js", encoding="utf-8").read()


def header(src):
    return src[src.index("const ROOT ="):src.index("const results = await parallel([")]


def entries(src):
    body = src.split("const results = await parallel([", 1)[1].rsplit("])\nreturn { results }", 1)[0]
    return [e.rstrip().rstrip(",") for e in re.split(r"\n(?=  \(\) => )", body.strip("\n"))]


def task_text(entry):
    """The template-literal task text of a rev/tbk entry: the last backtick string argument."""
    m = re.search(r"(?:rev|tbk)\('([^']+)'(?:, '[^']+')?, `(.*)`\)\s*$", entry, re.S)
    return m.group(1), m.group(2)


H = header(b2)
E1 = {}
for e in entries(b1) + entries(b2):
    if e.lstrip().startswith("() => rev(") or e.lstrip().startswith("() => tbk("):
        label, text = task_text(e)
        E1[label] = text
    elif "review:19" in e:
        E1["review:19"] = e
    elif "stage4-diagnose" in e:
        E1["stage4-diagnose"] = e
for k in ["doc-updates", "revnb-ks-dark", "gate", "prov-t3", "fix:16", "fix:17", "review:19", "stage4-diagnose"]:
    assert k in E1, k

# the review:19 and stage4 entries are whole agent() calls; take their prompt template literal
rv19 = re.search(r"agent\(`(.*?)`, \{ label: 'review:19'", E1["review:19"], re.S).group(1)
st4 = re.search(r"agent\(`(.*?)`, \{ label: 'stage4-diagnose'", E1["stage4-diagnose"], re.S).group(1)

H = H.replace("const STATE = `STATE (2026-10-08, phase 2b; all of it committed and verified by the lead):",
              "const STATE = `STATE (2026-10-08 10:00, phase 3a; all of it committed and verified by the lead): Revision documents "
              "KOHN_SHAM_DEFLATING_FIELD, DARK_SECTOR_HYPOTHESES and LOVELOCK_GKD are written and registered (commits ecb53b4, ae627be);")
H = H.replace("<your label>.progress.md", "<your log name>.progress.md")

out = ["export const meta = {",
       "  name: 'completion-phase-3a',",
       "  description: 'Completion phase 3a: resume the agents stopped by the session limit (chapters 16, 17, 19 with adversarial fix-verifiers; "
       "old Stage 4 diagnose-fix-verify; Lovelock comparison with the author; wave-1 document updates; T3 provenance; Revision notebooks 2-3; the gate) "
       "and the textbook tasks no agent owns (charge-conservation qualification; chapter 22 dark-sector results)',",
       "  phases: [",
       "    { title: 'Revision', detail: 'document updates, T3 provenance, notebooks 2-3, gate, Lovelock comparison' },",
       "    { title: 'Textbook', detail: 'chapters 16, 17, 19 (fix, verify, re-fix); charge qualification; chapter 22' },",
       "    { title: 'Old Stage 4', detail: 'diagnose, fix at the root, verify' },",
       "  ],",
       "}",
       H.rstrip()]
out.append(r"""
const LOGDIR = `${SP}/phase2b`
const RESUME = (log) => `RESUME NOTE (2026-10-08 10:00): an earlier run of this exact task was STOPPED by a session limit (about 08:50) before it finished. Its progress log is ${LOGDIR}/${log}.progress.md: read it FIRST and keep appending to it. Files it edited may be in the working tree in a half-finished state (see git status / git diff): inspect them, re-verify every earlier edit against its source (never trust it unchecked), keep what is correct, repair what is not, then finish the task. Do not redo verified work needlessly. Its scratch folder ${LOGDIR}/${log}/ may hold useful intermediate files.`
const revR = (label, ph, log, task) => agent(`${REVCOMMON}\n${STATE}\n${BOUND}\n${RESUME(log)}\nTASK (${label}): ${task}`, { label, phase: ph, schema: RESULT })
const tbkR = (label, log, task) => agent(`${TBCOMMON}\n${STATE}\n${BOUND}\n${RESUME(log)}\nTASK (${label}): ${task}`, { label, phase: 'Textbook', schema: RESULT })
const tbkN = (label, task) => agent(`${TBCOMMON}\n${STATE}\n${BOUND}\nTASK (${label}): ${task}`, { label, phase: 'Textbook', schema: RESULT })
const CH = { '16': '16-checking-the-solution-independently', '17': '17-a4-equations-with-kohn-sham-source', '19': '19-t3-kohn-sham-universes' }
const verifyFix = (nn, findingsSource, fixResult) => agent(`${TBCOMMON}\n${STATE}\n${BOUND}\nTASK (fix-verifier of chapter ${nn}; adversarial; do NOT edit files): A fixer claims to have fixed the review findings of chapter ${T}/chapters/${CH[nn]}.md. The findings: ${findingsSource}. The fixer's report (JSON): ${JSON.stringify(fixResult || {}).slice(0, 30000)}\nFor EVERY finding, check in the files themselves (not in the report) that the fix is real and correct, and that the fix did not introduce a new error (re-derive formulas, re-read numbers from the Revision records and from the notebooks' printed outputs). Run python ${T}/tools/nbkit.py check on every notebook of the chapter, the walk-through audit (${QUOTES}) and python ${T}/tools/check_chapter.py on the chapter. Report as findings ONLY what is still wrong (unfixed, wrongly fixed, newly broken), with concrete evidence; verified_ok lists the findings confirmed fixed.`, { label: `verify-fix:${nn}`, phase: 'Textbook', schema: FINDINGS })
const refix = (nn, v) => (v && v.findings && v.findings.length)
  ? tbkN(`refix:${nn}`, `You own chapter ${nn} (${T}/chapters/${CH[nn]}.md), its notebook builders, notebooks, PROVENANCE files and figures (${T}/notebooks/src/${nn}*.py, ${T}/notebooks/${nn}*, ${T}/figures/${nn}*). An adversarial fix-verifier found these remaining problems (JSON): ${JSON.stringify(v.findings).slice(0, 50000)}\n${FIXTAIL}`)
  : { files_changed: [], commands_run: [], all_checks_pass: !!v, failing: v ? [] : [`verify-fix:${nn} returned nothing`], key_results: [v ? `verify-fix:${nn}: every finding confirmed fixed` : `verify-fix:${nn}: no result`], open_items: [], summary: v ? `chapter ${nn}: fixes verified` : 'no verifier result' }
""")

def js(s):
    return "`" + s + "`"

tasks = []
